#include "gtest/gtest.h"
#include "../../inst/include/common/derived_quantity_report.hpp"
#include "../../inst/include/models/functors/catch_at_age.hpp"

namespace {

TEST(DerivedQuantityNamePattern, MatchesGlobWildcards) {
  EXPECT_TRUE(fims_report::MatchDerivedQuantityName("*biomass", "biomass"));
  EXPECT_TRUE(fims_report::MatchDerivedQuantityName("*biomass",
                                                    "spawning_biomass"));
  EXPECT_TRUE(fims_report::MatchDerivedQuantityName(
      "unfished_*", "unfished_spawning_biomass"));
  EXPECT_TRUE(fims_report::MatchDerivedQuantityName("*", "mortality_F"));
  EXPECT_FALSE(fims_report::MatchDerivedQuantityName("*biomass",
                                                     "numbers_at_age"));
  EXPECT_FALSE(fims_report::MatchDerivedQuantityName("biomass", "xbiomass"));
}

// DerivedQuantityReportRegistry
// IO correctness
TEST(DerivedQuantityReportRegistry, HandlesCorrectInput_AddsRequest) {
  fims_report::DerivedQuantityReportRegistry registry;
  fims_report::DerivedQuantityReportRequest request;
  request.model_id = 1;
  request.component_type =
      fims_report::DerivedQuantityComponentType::population;
  request.component_id = 12;
  request.quantity_name = "spawning_biomass";
  request.report_se = true;

  const auto& stored = registry.Add(request);

  EXPECT_EQ(registry.size(), static_cast<size_t>(1));
  EXPECT_TRUE(stored.report_se);
}

// IO correctness
TEST(DerivedQuantityReportRegistry, HandlesCorrectInput_AddsFleetRequest) {
  fims_report::DerivedQuantityReportRegistry registry;
  fims_report::DerivedQuantityReportRequest request;
  request.model_id = 1;
  request.component_type = fims_report::DerivedQuantityComponentType::fleet;
  request.component_id = 3;
  request.quantity_name = "index";

  const auto& stored = registry.Add(request);

  EXPECT_EQ(stored.quantity_name, "index");
}

// Edge handling
TEST(DerivedQuantityReportRegistry, HandlesEdge_ClearRemovesRequests) {
  fims_report::DerivedQuantityReportRegistry registry;
  fims_report::DerivedQuantityReportRequest request;
  request.model_id = 1;
  request.component_type = fims_report::DerivedQuantityComponentType::fleet;
  request.component_id = 3;
  request.quantity_name = "landings";

  registry.Add(request);
  registry.Clear();

  EXPECT_TRUE(registry.empty());
  EXPECT_EQ(registry.GetRequests().size(), static_cast<size_t>(0));
}

// Error handling
TEST(DerivedQuantityReportRegistry, ThrowsWhenRequestIsDuplicated) {
  fims_report::DerivedQuantityReportRegistry registry;
  fims_report::DerivedQuantityReportRequest request;
  request.model_id = 1;
  request.component_type = fims_report::DerivedQuantityComponentType::fleet;
  request.component_id = 3;
  request.quantity_name = "landings";

  registry.Add(request);

  EXPECT_THROW(registry.Add(request), std::invalid_argument);
}

// Error handling
TEST(DerivedQuantityReportRegistry, ThrowsWhenQuantityNameIsEmpty) {
  fims_report::DerivedQuantityReportRegistry registry;
  fims_report::DerivedQuantityReportRequest request;
  request.model_id = 1;
  request.component_type =
      fims_report::DerivedQuantityComponentType::population;
  request.component_id = 2;

  EXPECT_THROW(registry.Add(request), std::invalid_argument);
}

// FisheryModelBase report API
// IO correctness
TEST(FisheryModelBase, HandlesCorrectInput_ReportsPopulationDerivedQuantity) {
  fims_popdy::CatchAtAge<double> model;

  const auto& stored =
      model.ReportPopulationDerivedQuantity(2, "spawning_biomass", true);
  const auto& requests = model.GetDerivedQuantityReportRequests();

  EXPECT_EQ(requests.size(), static_cast<size_t>(1));
  EXPECT_EQ(stored.component_type,
            fims_report::DerivedQuantityComponentType::population);
  EXPECT_EQ(stored.component_id, static_cast<uint32_t>(2));
  EXPECT_EQ(stored.quantity_name, "spawning_biomass");
  EXPECT_TRUE(stored.report_se);
}

}  // namespace
